const US_MAP = { w: 860, h: 532 };

// Albers USA as fitted to the frame: the lower 48 on an equal-area conic
// (parallels 29.5 and 45.5), Alaska at 0.35 scale and Hawaii inset where
// the outlines put them.
const US_K = 1017.316, US_TX = 432.59, US_TY = 260.447;
function usRaw(lam, phi, p0, p1) {
  const s0 = Math.sin(p0), n = (s0 + Math.sin(p1)) / 2, c = 1 + s0 * (2 * n - s0);
  const r0 = Math.sqrt(c) / n, r = Math.sqrt(Math.max(0, c - 2 * n * Math.sin(phi))) / n;
  return [r * Math.sin(lam * n), r0 - r * Math.cos(lam * n)];
}
function usPart(lat, lon, rot, cen, par) {
  const R = Math.PI / 180;
  const lam = ((((lon + rot + 180) % 360) + 360) % 360 - 180) * R;
  const [x, y] = usRaw(lam, lat * R, par[0] * R, par[1] * R);
  const [cx, cy] = usRaw(cen[0] * R, cen[1] * R, par[0] * R, par[1] * R);
  return [x - cx, -(y - cy)];
}
// A place (latitude, longitude) on the frame; `st` names its state when
// known, so Alaska and Hawaii land in their insets.
function usProject(lat, lon, st) {
  if (st === "AK" || (!st && lat > 51 && lon < -129)) {
    const [u, v] = usPart(lat, lon, 154, [-2, 58.5], [55, 65]);
    return [US_TX - 0.307 * US_K + 0.35 * US_K * u, US_TY + 0.201 * US_K + 0.35 * US_K * v];
  }
  if (st === "HI" || (!st && lat < 23 && lon < -150)) {
    const [u, v] = usPart(lat, lon, 157, [-3, 19.9], [8, 18]);
    return [US_TX - 0.205 * US_K + US_K * u, US_TY + 0.212 * US_K + US_K * v];
  }
  const [u, v] = usPart(lat, lon, 96, [-0.6, 38.7], [29.5, 45.5]);
  return [US_TX + US_K * u, US_TY + US_K * v];
}
// The point `miles` from a place at a compass bearing (degrees), on the
// frame; `st` keeps a place in Alaska or Hawaii in its inset.
function usAt(lat, lon, miles, bearing, st) {
  const R = Math.PI / 180, d = miles / 3959, p1 = lat * R, l1 = lon * R, t = bearing * R;
  const p2 = Math.asin(Math.sin(p1) * Math.cos(d) + Math.cos(p1) * Math.sin(d) * Math.cos(t));
  const l2 = l1 + Math.atan2(Math.sin(t) * Math.sin(d) * Math.cos(p1), Math.cos(d) - Math.sin(p1) * Math.sin(p2));
  return usProject(p2 / R, l2 / R, st === "AK" || st === "HI" ? st : "48");
}
// A ring of equal miles around a place, as a path on the frame (the true
// circle on the globe, so it bends as the projection does).
function usRing(lat, lon, miles, st) {
  const pts = [];
  for (let b = 0; b <= 360; b += 4) {
    const [x, y] = usAt(lat, lon, miles, b, st);
    pts.push(x.toFixed(1) + "," + y.toFixed(1));
  }
  return "M" + pts.join("L") + "Z";
}
